import { chromium } from 'playwright';
import fs from 'node:fs';
import path from 'node:path';

const TARGET='https://www.statesideqm.com/collections/safety-rescue-climbing?preview_theme_id=158561894555';
const OUT='out/safety-browser-cert';
fs.mkdirSync(OUT,{recursive:true});
const report={target:TARGET,themeId:'158561894555',generatedAt:new Date().toISOString(),cases:[],failures:[]};
const cases=[{name:'desktop',viewport:{width:1440,height:1000},cols:3},{name:'mobile',viewport:{width:390,height:844},cols:2}];
const visibleScript=`e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>2&&r.height>2}`;

function fail(c,msg,data){const x=data===undefined?msg:`${msg}: ${JSON.stringify(data)}`;c.failures.push(x);report.failures.push(`${c.name}: ${x}`)}
async function installProbe(page){await page.addInitScript(()=>{window.__sqSafetyFlash=[];let last='';const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>2&&r.height>2};const scan=()=>{const m=document.querySelector('#MainContent');if(!m)return;const results=m.querySelector('.sq-refine-v3-results');const grids=[...m.querySelectorAll('.product-grid')].filter(vis);const outside=grids.filter(g=>!results||!results.contains(g));if(grids.length>1||outside.length){const sig=`${location.pathname}${location.search}|${grids.length}|${outside.length}`;if(sig!==last){last=sig;window.__sqSafetyFlash.push({t:Math.round(performance.now()),url:location.href,visible:grids.length,outside:outside.length})}}};const tick=()=>{try{scan()}catch{}requestAnimationFrame(tick)};requestAnimationFrame(tick)})}
async function ready(page,{filtered=false}={}){await page.waitForSelector('#MainContent',{timeout:90000});await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:90000});await page.waitForFunction(()=>window.__sqUniformColor?.ready===true,{timeout:90000});await page.waitForFunction(()=>{const side=document.querySelector('.sq-refine-v3-sidebar');return !![...(side?.querySelectorAll('details>summary')||[])].find(s=>(s.textContent||'').replace(/\s+/g,' ').trim()==='Shop by Color / Pattern')},{timeout:90000});if(filtered)await page.waitForSelector('[data-sq-ucp-results]',{state:'attached',timeout:90000});await page.waitForTimeout(800)}
async function snapshot(page,label){return page.evaluate(label=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>2&&r.height>2};const m=document.querySelector('#MainContent'),side=m?.querySelector('.sq-refine-v3-sidebar'),res=m?.querySelector('.sq-refine-v3-results');const summaries=[...(side?.querySelectorAll('details>summary')||[])].map(x=>(x.textContent||'').replace(/\s+/g,' ').trim());const colorDetails=[...(side?.querySelectorAll('details')||[])].filter(d=>((d.querySelector(':scope>summary')?.textContent||'').replace(/\s+/g,' ').trim()==='Shop by Color / Pattern'));const group=colorDetails[0]||null;const choices=[...(group?.querySelectorAll('input[data-sq-ucp-value]')||[])].map(i=>({value:i.dataset.sqUcpValue||'',checked:i.checked,label:(i.closest('label')?.querySelector('span')?.textContent||'').trim(),count:Number((i.closest('label')?.querySelector('.sq-ucp-count')?.textContent||'0').replace(/[^0-9]/g,''))||0}));const grids=[...(m?.querySelectorAll('.product-grid')||[])].filter(vis),outside=grids.filter(g=>!res?.contains(g));const filtered=res?.querySelector('[data-sq-ucp-results]');const fg=filtered?.querySelector('.product-grid');const filteredCards=fg?[...fg.children].filter(vis):[];const normalCards=[...(res?.querySelectorAll('.product-grid > .product-grid__item')||[])].filter(vis);const grid=fg&&vis(fg)?fg:grids.find(g=>res?.contains(g));const cols=grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0;const status=(filtered?.querySelector('[role="status"]')?.textContent||'').trim();const mm=status.match(/([0-9,]+)\s+matching products/i);const matchCount=mm?Number(mm[1].replace(/,/g,'')):0;const u=new URL(location.href);return{label,url:location.href,theme:window.Shopify?.theme?{id:String(window.Shopify.theme.id||''),role:String(window.Shopify.theme.role||'')}:null,refineReady:m?.dataset.sqRefineV3Ready||null,apiReady:!!window.__sqUniformColor?.ready,summaryCount:summaries.filter(x=>x==='Shop by Color / Pattern').length,colorGroupCount:colorDetails.length,choices,visibleGridCount:grids.length,outsideGridCount:outside.length,filteredVisible:vis(filtered),filteredCount:filteredCards.length,filteredLinks:filteredCards.map(x=>x.querySelector('a[href*="/products/"]')?.href||''),normalCount:normalCards.length,matchCount,cols,overflow:document.documentElement.scrollWidth>window.innerWidth+3,sqRoot:u.searchParams.get('sq_root'),sqUcp:u.searchParams.getAll('sq_ucp'),sqPerPage:u.searchParams.get('sq_per_page'),sqViewPage:u.searchParams.get('sq_view_page'),sizes:[...(m?.querySelectorAll('input[name="sq_per_page_control"]')||[])].map(i=>({value:i.value,checked:i.checked})),pager:[...(filtered?.querySelectorAll('.sq-refine-v3-pager a')||[])].map(a=>({text:a.textContent.trim(),href:a.href})),flash:window.__sqSafetyFlash||[]}},label)}
function checks(c,s,cols,phase){if(s.theme?.id&&s.theme.id!=='158561894555')fail(c,`${phase} wrong theme`,s.theme);if(s.theme?.role==='main')fail(c,`${phase} is live/main theme`,s.theme);if(s.refineReady!=='true'||!s.apiReady)fail(c,`${phase} V3/color code not ready`);if(s.summaryCount!==1)fail(c,`${phase} Shop by Color / Pattern summary count`,s.summaryCount);if(s.colorGroupCount!==1)fail(c,`${phase} color group count`,s.colorGroupCount);if(!s.choices.length)fail(c,`${phase} choices empty`);if(s.outsideGridCount!==0)fail(c,`${phase} visible legacy grid outside V3 results`,s.outsideGridCount);if(s.visibleGridCount!==1)fail(c,`${phase} visible grid count`,s.visibleGridCount);if(s.cols!==cols)fail(c,`${phase} columns`,{got:s.cols,want:cols});if(s.overflow)fail(c,`${phase} horizontal overflow`);if(s.sqRoot==='uniforms')fail(c,`${phase} leaked sq_root=uniforms`);const vals=s.sizes.map(x=>x.value).sort();if(JSON.stringify(vals)!==JSON.stringify(['100','250','50']))fail(c,`${phase} page-size controls`,vals);if(s.flash.length)fail(c,`${phase} legacy/duplicate grid flash detected`,s.flash)}
async function shot(page,name,phase){await page.screenshot({path:path.join(OUT,`${name}-${phase}.png`),fullPage:true})}
async function getChoice(page,value){return page.locator(`.sq-refine-v3-sidebar input[data-sq-ucp-value="${String(value).replace(/"/g,'\\"')}"]`).first()}

async function run(browser,spec){const ctx=await browser.newContext({viewport:spec.viewport}),page=await ctx.newPage();page.setDefaultTimeout(60000);page.setDefaultNavigationTimeout(120000);const c={name:spec.name,viewport:spec.viewport,phases:{},failures:[],consoleErrors:[],pageErrors:[],requestFailures:[]};report.cases.push(c);await installProbe(page);page.on('console',m=>{if(m.type()==='error'){const loc=m.location(),text=m.text(),url=loc?.url||'';if(url.includes('statesideqm.com')||text.includes('[SQ'))c.consoleErrors.push({text,url})}});page.on('pageerror',e=>c.pageErrors.push(String(e)));page.on('requestfailed',r=>{if(r.url().includes('statesideqm.com'))c.requestFailures.push({url:r.url(),error:r.failure()?.errorText||''})});try{
  const resp=await page.goto(TARGET,{waitUntil:'domcontentloaded'});c.httpStatus=resp?.status()||null;if(!resp||resp.status()>=400)fail(c,'initial HTTP failure',c.httpStatus);await ready(page);let s=await snapshot(page,'initial');c.phases.initial=s;checks(c,s,spec.cols,'initial');if(!s.normalCount)fail(c,'initial normal products missing');await shot(page,c.name,'initial');
  const choice=s.choices.filter(x=>x.value&&x.count>0).sort((a,b)=>b.count-a.count)[0];if(!choice)throw new Error('No populated color/pattern choice available');c.selectedChoice=choice;
  let box=await getChoice(page,choice.value);await box.scrollIntoViewIfNeeded();await Promise.all([page.waitForURL(u=>u.searchParams.getAll('sq_ucp').includes(choice.value),{timeout:45000}),box.check()]);await ready(page,{filtered:true});s=await snapshot(page,'selected');c.phases.selected=s;checks(c,s,spec.cols,'selected');if(!s.sqUcp.includes(choice.value))fail(c,'selected URL missing sq_ucp',s.sqUcp);if(!s.choices.find(x=>x.value===choice.value)?.checked)fail(c,'selected checkbox not checked');if(s.matchCount!==choice.count)fail(c,'matching product count differs from populated choice count',{choiceCount:choice.count,matchCount:s.matchCount});if(!s.filteredVisible||!s.filteredCount)fail(c,'matching products did not render');if(s.filteredLinks.some(x=>!x.includes('/products/')))fail(c,'filtered result missing product link');if(s.outsideGridCount!==0||s.visibleGridCount!==1)fail(c,'filtered duplicate/native grid leak',{visible:s.visibleGridCount,outside:s.outsideGridCount});await shot(page,c.name,'selected');
  const size100=page.locator('input[name="sq_per_page_control"][value="100"]').first();if(!(await size100.count()))fail(c,'100 products/page control missing');else{await Promise.all([page.waitForURL(u=>u.searchParams.get('sq_per_page')==='100'&&u.searchParams.get('sq_view_page')==='1',{timeout:45000}),size100.check()]);await ready(page,{filtered:true});s=await snapshot(page,'page-size-100');c.phases['page-size-100']=s;checks(c,s,spec.cols,'page-size-100');if(!s.sizes.find(x=>x.value==='100')?.checked)fail(c,'100 page-size radio not checked');if(s.filteredCount!==Math.min(100,s.matchCount))fail(c,'100 page-size rendered wrong count',{rendered:s.filteredCount,matches:s.matchCount});await shot(page,c.name,'page-size-100')}
  if(s.matchCount>100){const next=page.locator('[data-sq-ucp-results] .sq-refine-v3-pager a').filter({hasText:/^Next$/i}).first();if(!(await next.count()))fail(c,'Next pager missing despite multiple filtered pages',{matches:s.matchCount,pageSize:100});else{const first=s.filteredLinks[0];await Promise.all([page.waitForURL(u=>u.searchParams.get('sq_view_page')==='2',{timeout:45000}),next.click()]);await ready(page,{filtered:true});s=await snapshot(page,'page-2');c.phases['page-2']=s;checks(c,s,spec.cols,'page-2');if(s.sqViewPage!=='2')fail(c,'pagination URL did not become page 2',s.sqViewPage);if(!s.sqUcp.includes(choice.value))fail(c,'pagination lost sq_ucp');if(s.filteredLinks[0]&&first===s.filteredLinks[0])fail(c,'pagination first product did not change');await shot(page,c.name,'page-2')}}else c.paginationNotApplicable={matches:s.matchCount,pageSize:100};
  box=await getChoice(page,choice.value);await box.scrollIntoViewIfNeeded();await Promise.all([page.waitForURL(u=>!u.searchParams.has('sq_ucp'),{timeout:45000}),box.uncheck()]);await ready(page);s=await snapshot(page,'cleared');c.phases.cleared=s;checks(c,s,spec.cols,'cleared');if(s.sqUcp.length)fail(c,'clear left sq_ucp',s.sqUcp);if(s.choices.some(x=>x.checked))fail(c,'clear left color checkbox checked');if(!s.normalCount)fail(c,'clear did not restore normal products');await shot(page,c.name,'cleared');
  await page.goto(TARGET,{waitUntil:'domcontentloaded'});await ready(page);await page.evaluate(()=>{const u=new URL(location.href);u.searchParams.set('sq_root','uniforms');history.replaceState({},'',u.pathname+u.search)});box=await getChoice(page,choice.value);await box.scrollIntoViewIfNeeded();await Promise.all([page.waitForURL(u=>u.searchParams.has('sq_ucp'),{timeout:45000}),box.check()]);await ready(page,{filtered:true});s=await snapshot(page,'stale-root');c.phases['stale-root']=s;checks(c,s,spec.cols,'stale-root');if(s.sqRoot==='uniforms')fail(c,'stale sq_root=uniforms survived Safety color selection');if(!s.sqUcp.includes(choice.value))fail(c,'stale-root test failed to set sq_ucp');await shot(page,c.name,'stale-root');
  if(c.consoleErrors.length)fail(c,'browser console errors',c.consoleErrors);if(c.pageErrors.length)fail(c,'browser/runtime errors',c.pageErrors);if(c.requestFailures.length)fail(c,'storefront request failures',c.requestFailures);
}catch(e){fail(c,'uncaught certification error',e?.stack||String(e));try{await shot(page,c.name,'failure')}catch{}}finally{await ctx.close()}}

const browser=await chromium.launch({headless:true});for(const spec of cases)await run(browser,spec);await browser.close();report.passed=report.failures.length===0;fs.writeFileSync(path.join(OUT,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.passed)process.exitCode=2;
